<script setup>
import {useSuggestedCompetence} from '../lib/context-preferences.js';
import {ref,watch,computed} from 'vue';import {state,company,api,scope,useResource,notify} from '../lib/workspace';
import {can,allowedApi,writable} from '../lib/workspace';import {reconcileAccountMappings} from '../lib/account-references';
let accountIdentities={},sequence=0;
const competence=ref('');useSuggestedCompetence(state,competence);
const query=ref(''),page=ref(1);
watch(query,()=>page.value=1);import {money,normalized} from '../lib/format';
const participants=ref({});
const accounts=ref({}),centers=ref({}),companyCode=ref(''),batch=ref('1'),preview=ref(null),result=ref(null),error=ref(''),busy=ref(false),reviewed=ref(false),ascii=ref(false);
const {data,reload:reloadMappings}=useResource(async()=>{if(!state.companyId||!competence.value)return {accounts:[],centers:[]};const [accounts,centers,journals]=await Promise.all([allowedApi('accounting.accounts',scope('/accounts')),allowedApi('accounting.cost_centers',scope('/cost-centers')),allowedApi('accounting.journals',scope(`/journals?period=${competence.value}`),[])]);const parties=[...new Map(journals.flatMap(j=>j.lines||[]).filter(l=>l.participant_id).map(l=>[l.participant_id,{id:l.participant_id,name:l.participant_name||String(l.participant_id)}])).values()];return {accounts,centers,parties};},{accounts:[],centers:[]});
watch(competence,()=>reloadMappings?.());
const matchingAccounts=computed(()=>data.value.accounts.filter(a=>a.analytical&&a.id>0&&normalized(`${a.access_code} ${a.name} ${a.classifier}`).includes(normalized(query.value))));
const mappingAccounts=computed(()=>matchingAccounts.value.slice((page.value-1)*200,page.value*200));
watch(()=>state.companyId,()=>{accounts.value={};participants.value={};accountIdentities={};centers.value={};companyCode.value=company.value?.prosoft_code||'';preview.value=null;result.value=null;reviewed.value=false;ascii.value=false;},{immediate:true});
watch(()=>data.value,()=>{const reconciled=reconcileAccountMappings(accounts.value,accountIdentities,data.value.accounts);accounts.value=reconciled.mappings;accountIdentities=reconciled.identities;if(reconciled.idsChanged){preview.value=null;result.value=null;reviewed.value=false;ascii.value=false;}for(const p of data.value.parties||[])participants.value[p.id]??={code:'',third_type:'normal',confirmed:false};for(const c of data.value.centers)centers.value[c.id]??={code:c.prosoft_code||c.code,confirmed:false};});
watch(()=>[state.companyId,state.module,competence.value],()=>{sequence++;busy.value=false;preview.value=null;result.value=null;reviewed.value=false;ascii.value=false;},{flush:'sync'});
async function run(confirm=false){if(busy.value||!state.companyId||!competence.value)return;const token=++sequence;busy.value=true;error.value='';const cid=state.companyId,period=competence.value;try{const payload={period,company_code:companyCode.value,batch:batch.value,accounts:accounts.value,centers:centers.value,participants:participants.value,allow_ascii:ascii.value,destination_reviewed:reviewed.value,preview_hash:preview.value?.preview_hash};const r=await api(scope(`/prosoft/${confirm?'confirm':'preview'}`,cid),{method:'POST',body:payload});if(token!==sequence||cid!==state.companyId||period!==competence.value)return;if(confirm){result.value={...r,cid};notify('Arquivo de integração preparado.');}else{preview.value=r;result.value=null;}}catch(e){if(token===sequence)error.value=e.message;}finally{if(token===sequence)busy.value=false;}}
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">INTEGRAÇÃO CONTÁBIL</div><h1>Exportação Prosoft</h1><p>CTBLCTOS · registros LC1 de 448 posições e LC2 de 342 posições.</p></div></header><p class="message warning">Confira empresa, contas e terceiros na instalação de destino. A exportação não significa homologação ou importação na Prosoft.</p><p v-if="error" class="message error" role="alert">{{error}}</p><section class="panel report-controls"><div class="form-grid"><label>Competência da exportação<select v-model="competence" :disabled="busy||!state.companyId"><option value="">Selecione</option><option v-for="m in 12" :key="m" :value="`${state.period.slice(0,4)}-${String(m).padStart(2,'0')}`">{{String(m).padStart(2,'0')}}/{{state.period.slice(0,4)}}</option></select></label><label>Código da empresa na Prosoft<input v-model="companyCode" maxlength="4" inputmode="numeric"/></label><label>Lote<input v-model="batch" maxlength="5" inputmode="numeric"/></label></div><div class="section-label">Mapeamento das contas <span>Confirme cada conta utilizada na competência.</span></div><div class="actions"><input v-model="query" aria-label="Pesquisar mapeamentos de contas" placeholder="Buscar acesso, classificador ou nome"/><span>{{matchingAccounts.length}} contas · até 200 por página</span><button class="button small" :disabled="page===1" @click="page--">Anterior</button><button class="button small" :disabled="page*200>=matchingAccounts.length" @click="page++">Próxima</button></div><div class="table-scroll"><table><thead><tr><th>Conta da Escritura</th><th>Acesso Prosoft</th><th>Uso de terceiro</th><th>Código do terceiro</th><th>Tipo</th><th>Conferido</th></tr></thead><tbody><template v-for="a in mappingAccounts" :key="a.id"><tr v-if="accounts[a.id]"><td>{{a.access_code}} · {{a.name}}</td><td><input v-model="accounts[a.id].code" maxlength="5" :aria-label="`Acesso Prosoft da conta ${a.access_code}`"/></td><td><select v-model="accounts[a.id].third_mode"><option value="none">Sem terceiro</option><option value="optional">Opcional</option><option value="required">Obrigatório</option></select></td><td><input v-model="accounts[a.id].third" maxlength="14"/></td><td><select v-model="accounts[a.id].third_type"><option value="normal">Normal</option><option value="free">Livre (sufixo L)</option></select></td><td><input type="checkbox" v-model="accounts[a.id].confirmed" :aria-label="`Confirmar conta ${a.access_code}`"/></td></tr></template></tbody></table></div><div v-if="data.centers.length" class="section-label">Centros de custo</div><div v-for="c in data.centers" :key="c.id" class="form-grid"><template v-if="centers[c.id]"><label>{{c.code}} · {{c.name}}<input v-model="centers[c.id].code" maxlength="5"/></label><label class="inline-choice"><input type="checkbox" v-model="centers[c.id].confirmed"/>Conferido no destino</label></template></div><div v-if="data.parties?.length" class="section-label">Terceiros das partidas</div><div v-for="p in data.parties||[]" :key="p.id" class="form-grid"><template v-if="participants[p.id]"><label>{{p.name}} · código no destino<input v-model="participants[p.id].code" maxlength="14"/></label><label>Tipo<select v-model="participants[p.id].third_type"><option value="normal">Normal</option><option value="free">Livre (sufixo L)</option></select></label><label class="inline-choice"><input type="checkbox" v-model="participants[p.id].confirmed"/>Conferido no destino</label></template></div><button class="button primary" v-allow="['accounting.prosoft','export']" @click="run(false)" :disabled="busy">Gerar prévia</button></section><section v-if="preview" class="panel report-controls"><h2>Conferência do lote</h2><p>{{preview.filename}} · {{preview.manifest.journals}} lançamentos · {{preview.manifest.records}} registros</p><p>Débitos {{money(preview.manifest.debit_cents)}} · créditos {{money(preview.manifest.credit_cents)}}</p><div class="table-scroll"><table><thead><tr><th>Ordem</th><th>Lançamento</th><th>Partidas</th><th>Total</th></tr></thead><tbody><tr v-for="r in preview.manifest.trace" :key="r.order"><td>{{r.order}}</td><td>#{{r.journal_id}} · {{r.journal_number}}</td><td>{{r.line_count}}</td><td>{{money(r.total_cents)}}</td></tr></tbody></table></div><details><summary>Conversões de texto para ASCII ({{preview.manifest.text_changes.length}})</summary><p v-for="(c,i) in preview.manifest.text_changes" :key="i">{{c.field}}: {{c.original}} → {{c.exported}}</p></details><label class="inline-choice"><input type="checkbox" v-model="ascii"/>Revisei e aceito as conversões de texto exibidas.</label><label class="inline-choice"><input type="checkbox" v-model="reviewed"/>Conferi a empresa, as contas, terceiros e centros no destino.</label><button class="button primary" v-allow="['accounting.prosoft','export']" @click="run(true)" :disabled="busy||!reviewed">Confirmar exportação</button><p v-if="result"><a class="button outline" :href="`/api/companies/${result.cid}/exports/${result.id}/download`" download>Baixar {{result.filename}}</a></p><small class="wrap-anywhere">SHA-256: {{preview.sha256}}</small></section></div></template>
